def get_sent_log():
    try:
        with open("quote_log.json", "r") as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return []


def save_sent_log(log):
    try:
        with open("quote_log.json", "w") as f:
            json.dump(log[-50:], f)
    except Exception:
        pass


def send_quote():
    sent_log = get_sent_log()
    available = [q for q in quotes if q["text"] not in sent_log]
    if not available:
        available = quotes

    quote = random.choice(available)

    message = (
        f"💬 یک جمله، یک نفس\n\n"
        f"«{quote['text']}»\n\n"
        f"📖 از: «{quote['book']}» – {quote['author']}\n\n"
        f"📚 لیبرو درمانی\n"
        f"کتاب مناسبِ حال، نه حالِ مناسبِ کتاب.\n\n"
        f"{quote['tags']}"
    )

    url = f"https://api.telegram.org/bot{BOT_TOKEN}/sendMessage"
    response = requests.post(url, data={
        "chat_id": CHANNEL_ID,
        "text": message,
        "parse_mode": "HTML"
    })

    if response.status_code == 200:
        sent_log.append(quote["text"])
        save_sent_log(sent_log)
        print(f"ارسال شد: {quote['book']} - {quote['author']}")
    else:
        print(f"خطا: {response.text}")


if __name__ == "__main__":
    send_quote()
